import React, { useEffect, useRef, useState } from 'react';
import { MapPin } from 'lucide-react';

interface LocationData {
  place_id: string;
  description: string;
  lat: number;
  lng: number;
}

interface LocationAutocompleteProps {
  value: string;
  onChange: (location: string, locationData?: LocationData) => void;
  placeholder?: string;
  className?: string;
  required?: boolean;
}

declare global {
  interface Window {
    google: any;
  }
}

const LocationAutocomplete: React.FC<LocationAutocompleteProps> = ({
  value,
  onChange,
  placeholder = "Search for a location...",
  className = "",
  required = false
}) => {
  const inputRef = useRef<HTMLInputElement>(null);
  const autocompleteRef = useRef<any>(null);
  // const [isLoading, setIsLoading] = useState(false);

  useEffect(() => {
    // Check if Google Places API is available
    if (window.google && window.google.maps && window.google.maps.places && inputRef.current) {
      // Initialize Google Places Autocomplete
      autocompleteRef.current = new window.google.maps.places.Autocomplete(inputRef.current, {
        types: ['establishment', 'geocode'],
        componentRestrictions: { country: 'us' }, // Restrict to US for now
        fields: ['place_id', 'formatted_address', 'geometry', 'name']
      });

      autocompleteRef.current.addListener('place_changed', () => {
        const place = autocompleteRef.current.getPlace();

        if (place.geometry && place.geometry.location) {
          const locationData: LocationData = {
            place_id: place.place_id,
            description: place.formatted_address || place.name,
            lat: place.geometry.location.lat(),
            lng: place.geometry.location.lng()
          };

          onChange(place.formatted_address || place.name, locationData);
        } else {
          // Fallback if no geometry is available
          onChange(place.formatted_address || place.name || value);
        }
      });
    }

    // Add listener for input changes (works with or without Google Places)
    if (inputRef.current) {
      const handleInputChange = (e: Event) => {
        const target = e.target as HTMLInputElement;
        onChange(target.value);
      };

      inputRef.current.addEventListener('input', handleInputChange);

      return () => {
        if (inputRef.current) {
          inputRef.current.removeEventListener('input', handleInputChange);
        }
        if (autocompleteRef.current) {
          window.google?.maps?.event?.clearInstanceListeners(autocompleteRef.current);
        }
      };
    }
  }, [onChange, value]);

  return (
    <div className="relative">
      <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
        <MapPin className="h-5 w-5 text-gray-400" />
      </div>
      <input
        ref={inputRef}
        type="text"
        value={value}
        placeholder={placeholder}
        required={required}
        className={`w-full pl-10 pr-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-blue-500 ${className}`}
        autoComplete="off"
      />
      {/* Loading indicator can be added here when needed */}
    </div>
  );
};

export default LocationAutocomplete;
